def preserve_saved_blueprints(apps, schema_editor):
    Plan = apps.get_model("aa_industry_planner", "ProductionPlan")
    Override = apps.get_model("aa_industry_planner", "PlanBlueprintOverride")
    ItemType = apps.get_model("eve_sde", "ItemType")
    alias = schema_editor.connection.alias
    for plan in Plan.objects.using(alias).only("pk", "snapshot").iterator(chunk_size=200):
        snapshot = plan.snapshot or {}
        Plan.objects.using(alias).filter(pk=plan.pk).update(
            use_inventory=bool(snapshot.get("inventory_used", True))
        )
        values = {}
        for tid, node in snapshot.get("nodes", {}).items():
            if (node.get("recipe") or {}).get("activity") != "manufacturing" or not node.get(
                "context"
            ):
                continue
            try:
                item_id = int(tid)
                me = int(node["context"].get("me", 0))
                te = int(node["context"].get("te", 0))
            except (TypeError, ValueError):
                continue
            if 0 <= me <= 10 and 0 <= te <= 20:
                values[item_id] = (me, te)
        known = ItemType.objects.using(alias).filter(pk__in=values).values_list("pk", flat=True)
        Override.objects.using(alias).bulk_create(
            [
                Override(
                    plan_id=plan.pk,
                    item_type_id=tid,
                    material_efficiency=values[tid][0],
                    time_efficiency=values[tid][1],
                )
                for tid in known
            ],
            ignore_conflicts=True,
        )


